class Font
{
public:
    enum HORIZJUST { HORIZJUST_CENTER };
    enum VERTJUST { VERTJUST_CENTER };
};

class stringx
{
    char data[8];

public:
    stringx(const stringx &);
    ~stringx();
};

class color32
{
    unsigned int value;
};

class TextString
{
protected:
    Font *font;
    stringx text;
    float x;
    float y;
    int z;
    Font::HORIZJUST hJustify;
    Font::VERTJUST vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;

public:
    TextString(Font *f, stringx t, float x1, float y1, int z1, float s,
               const Font::HORIZJUST horizJust,
               const Font::VERTJUST vertJust, color32 col)
    {
        cons(f, t, x1, y1, z1, s, horizJust, vertJust, false, col);
    }
    virtual ~TextString();
    virtual void Update(float);

protected:
    virtual void cons(Font *f, stringx t, float x1, float y1, int z1, float s,
                      const Font::HORIZJUST horizJust,
                      const Font::VERTJUST vertJust, bool no_col, color32 col);
};

class BouncingText : public TextString
{
protected:
    float targetScale;
    float speed;

public:
    BouncingText(Font *f, stringx t, float x1, float y1, int z1, float s,
                 const Font::HORIZJUST horizJust,
                 const Font::VERTJUST vertJust, color32 col);
    virtual void Update(float);
};

BouncingText::BouncingText(Font *f, stringx t, float x1, float y1, int z1,
                           float s, const Font::HORIZJUST horizJust,
                           const Font::VERTJUST vertJust, color32 col)
    : TextString(f, t, x1, y1, z1, s, horizJust, vertJust, col)
{
    targetScale = scale;
    speed = 1.0f;
}
